('barcelona-jga-girls-weekend','JGA Barcelona — Spa, Katamaran & Beach-Nightlife','Das Nr.-1-Ziel für den Junggesellinnenabschied: römisches Spa im Gewölbe, Cava im Born, Katamaran vor der Skyline und nachts die Strand-Clubs der Barceloneta.',null,null,'PD24 Redaktion','public','completed',true,array['jga','girls-trip','weekend','europe','spain','nightlife','wellness','road-trip'],2,array['ES'],'party','medium',$$[{"citySlug":"es-barcelona-born","cityLabel":"Barcelona · Born & Gòtic","lat":41.3851,"lng":2.1818,"nights":1,"planSummary":"Freitag-Ankunft: durch die Gassen des Gotischen Viertels, dann zwei Stunden Kerzenlicht-Spa im Aire und abends Cava und Tapas im Born.","plannedStops":[{"label":"Ankommen im Gòtic","hint":"Bummel durch Barri Gòtic und El Born — Gassen, Plätze, erste Fotos","time":"15:30","itemName":"Barri Gòtic"},{"label":"Aire Ancient Baths","hint":"Candle-lit Thermalbäder im Gewölbe — der Hen-Party-Klassiker, Monate vorher buchen","time":"17:00","itemName":"Aire Ancient Baths Barcelona"},{"label":"Cava-Auftakt","hint":"Winzige Cava-Institution seit 1929 — Gläser hoch zur Eröffnung","time":"19:30","itemName":"El Xampanyet"},{"label":"Tapas-Dinner","hint":"Tapas-Tour durch den Born, von Bar zu Bar","time":"20:30","itemName":"Carrer de Montcada Tapas"},{"label":"Rooftop-Absacker","hint":"Cocktails über den Dächern der Altstadt","time":"22:30","itemName":"Terraza del Hotel Colón"}]},{"citySlug":"es-barcelona-beach","cityLabel":"Barcelona · Strand & Nightlife","lat":41.3786,"lng":2.1925,"nights":1,"planSummary":"Der Kerntag: Brunch, Katamaran-Segeln vor der Skyline, Eisbar am Strand und nachts Beach-Club — das volle Barcelona-Programm.","plannedStops":[{"label":"Brunch","hint":"Später Start mit Pancakes und Flat White — Kraft tanken","time":"10:30","itemName":"Brunch & Cake Barcelona"},{"label":"Katamaran-Tour","hint":"Segeln ab Port Olímpic mit Cava an Bord — Skyline vom Wasser","time":"12:30","itemName":"Katamaran Port Olímpic"},{"label":"Strandnachmit