('lissabon-jga-girls-weekend','JGA Lissabon — Rooftops, LX Factory & Fado','Eine der coolsten Städte Europas für den Junggesellinnenabschied: Sunset auf dem Parkhaus-Rooftop, Kreativareal LX Factory, Pastéis de Nata und eine Fado-Nacht in Alfama.',null,null,'PD24 Redaktion','public','completed',true,array['jga','girls-trip','weekend','europe','portugal','food','nightlife','road-trip'],2,array['PT'],'friends','medium',$$[{"citySlug":"pt-lissabon-chiado","cityLabel":"Lissabon · Chiado & Bairro Alto","lat":38.7118,"lng":-9.1427,"nights":1,"planSummary":"Freitag-Ankunft: Bummel durch Chiado, Sundowner auf dem berühmten Parkhaus-Rooftop und abends Petiscos und Fado in den Gassen.","plannedStops":[{"label":"Chiado-Bummel","hint":"Boutiquen, Azulejos und das älteste Café der Stadt (A Brasileira)","time":"15:30","itemName":"Chiado Lissabon"},{"label":"Park Bar","hint":"Rooftop auf einem Parkhausdeck — der beste Sunset-Blick über Tejo und Brücke","time":"17:30","itemName":"Park Bar Lissabon"},{"label":"Petiscos-Dinner","hint":"Moderne portugiesische Kleinigkeiten zum Teilen","time":"19:30","itemName":"Taberna da Rua das Flores"},{"label":"Fado-Nacht","hint":"Kult-Fado-Kneipe — eng, laut, unvergesslich","time":"21:30","itemName":"Tasca do Chico"},{"label":"Bairro-Alto-Runde","hint":"Von Bar zu Bar durch das Ausgehviertel — alles fußläufig","time":"23:00","itemName":"Bairro Alto"}]},{"citySlug":"pt-lissabon-lxfactory","cityLabel":"Lissabon · LX Factory & Belém","lat":38.7036,"lng":-9.1785,"nights":1,"planSummary":"Der Kerntag: Brunch und Shopping im Kreativareal unter der Brücke, Pastéis in Belém, Sunset auf dem Topo und Abschluss im Time Out Market.","plannedStops":[{"label":"Brunch in der LX Factory","hint":"Brasilianisch inspirierter Brunch mit Livemusik am Fluss","time":"10:30","itemName":"Botequim Bottega LX Factory"},{"label":"LX-Factory-Bummel","hint":"Concept Stores, Streetart und die Bücherkathedrale Ler Devagar","time":"12:00","itemName":"LX Factory"},{"label":"Pastéis de Belém","hint":"Das Original seit 1837 — warm, mit Zimt","time":"14:00","itemName":"Pastéis de Belém"},{"label":"Torre & Uferweg","hint":"Fotostopp am Torre de Belém und Spaziergang am Tejo","time":"15:30","itemName":"Torre de Belém"},{"label":"Sunset & Ausklang","hint":"Rooftop-Sundowner, danach Dinner im Time Out Market","time":"18:00","itemName":"Time Out Market Lissabon"}]}]$$),
